package com.nexushr.controller; import com.nexushr.model.Department; import com.nexushr.repo.DepartmentRepository; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/departments") public class DepartmentController{final DepartmentRepository r; public DepartmentController(DepartmentRepository r){this.r=r;} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')") @GetMapping public List<Department> all(){return r.findAll();} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @PostMapping public Department create(@RequestBody Department d){return r.save(d);} }
